INSERT INTO `recipes` (`name`, `image`, `steps`, `rating`, `diff`, `id`, `user_id`, `category`) VALUES
('Roast Beef', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/recipe_1.jpg', '1. Salt the roast and let it come to room temp:\r\nThe beef should be brought as close to room temperature as possible before you start to roast it, so that it cooks more evenly. Remove it from the refrigerator at least 1 hour, preferably 2 hours, before cooking. Open the wrapping, sprinkle all sides with salt, and wrap it up again.\r\n\r\n2. Preheat the oven to 375°F:\r\n(190°C). Move a rack to the center of the oven, and place the other one underneath.\r\n\r\n3. Insert slivers of garlic into the roast:\r\nPat the roast dry with paper towels. Use the tip of a sharp knife to make 8 to 10 small incisions around the roast. Put a sliver of garlic into each cut.\r\n\r\n4. Rub the roast with olive oil, then season:\r\nRub olive oil all over the roast. Sprinkle it all around with salt and pepper.\r\n\r\n5. Put the roast on the rack with a pan below:\r\nPlace the roast directly on the middle oven rack, fatty side up, with a roasting pan to catch the drippings on the rack beneath it.\r\n\r\nPlacing the roast directly on the rack like this with a pan on the rack below creates a convection type environment in the oven, allowing the hot air to more easily circulate around the roast, so you don\'t have to turn the roast as it cooks.\r\n\r\nPlace the roast, fat-side up so that as the fat bathes the entire roast in flavor as it melts.\r\n\r\n6. Brown at 375°F, then lower the heat to 225°F:\r\nCook the roast initially at 375°F (190°C) for half an hour, to brown it. Then lower the heat to 225°F (107°C). The roast should take somewhere from 1 1/2 to 2 1/2 hours more to cook.\r\n\r\nThe shape of the roast will affect the cooking time. If your roast is long and narrow, rather than a more round shape, it may take less time to cook, so keep an eye on it.\r\n\r\n7. Roast to an internal temp of 135°F to 140°F:\r\nWhen juices start to drip from the roast, and it is browned on the outside, check the roast\'s internal temperature with a meat thermometer. Remove the roast from the oven when the internal temperature of the roast is 135°F to 140°F (for medium rare meat).\r\n\r\n8. Make the gravy as the roast rests:\r\nPlace the roast on a cutting board and tent it with aluminum foil to keep it warm. Let it rest for 20 to 30 minutes before cutting. (Resting the cooked roast is important. If you cut into it too soon, the roast will lose more of its juices.)\r\n\r\nTo make the gravy: Remove the dripping pan from the oven and place on the stove top at medium heat. Note that if you are pulling the roast out early, for rare or a medium rare level of doneness, you may not have a lot of drippings. Hopefully you will have some. If not, you may want to leave the roast in a little longer at even lower heat, 175°F, to ease some more drippings out of it.\r\n\r\nAdd some water, red wine, or beef stock to the drippings to deglaze (loosen the drippings from the pan). Dissolve a tablespoon of cornstarch in a little water and add to the drip pan. Stir quickly while the gravy thickens to avoid lumping.\r\n\r\nYou can add a little butter if there is not a lot of fat in the drippings. Add salt and pepper to taste. Mom adds some fresh thyme too if she has some.\r\n\r\n9. Slice and serve:\r\nAfter the roast has had a chance to rest a bit (and reabsorb its juices), thinly slice the roast to serve. (A sturdy long bread knife works well for slicing roasts.)\r\n\r\nPour the gravy over the slices or serve on the side.', 1, 3, 1, 1, 'lunch'),
('Shrimp pasta', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/recipe_2.jpg', '1. In a large pot of boiling salted water, cook the pasta according to package instructions; drain well and reserve 1 cup of pasta water.\r\n\r\n2. In a large skillet over medium high heat, melt two tablespoons butter. Add shrimp, salt and crushed red pepper, and cook stirring occasionally, until shrimp is opaque pink, about 2-3 minutes. Remove from heat and set aside.\r\n\r\n3. In the same skillet, add the remaining butter and garlic and cook until fragrant, about one minute. Turn off the heat, add the lemon juice, pasta water and parmesan cheese and stir to combine. Transfer the spaghetti to the skillet and toss with the sauce.\r\n\r\n4. Add the shrimp on top and garnish with parsley. Serve immediately.', 3.5, 4, 2, 1, ''),
('Hamburger', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67d1009382943_lunch_image.jpg', '1. Set out a large mixing bowl. Add in the ground beef, crushed crackers, egg, Worcestershire sauce, milk, salt, garlic powder, onion powder, and pepper. Mix by hand until the meat mixture is smooth, but stop once the mixture looks even. (Overmixing can create a dense heavy texture.)\r\n\r\n2. Press the meat down in the bowl, into an even disk. Use a knife to cut and divide the hamburger patty mixture into 6 – 1/3 pound grill or skillet patties, or 12 thin griddle patties.\r\n\r\n3. Set out a baking sheet, lined with wax paper or foil, to hold the patties. One at a time, gather the patty mix and press firmly into patties. Shape them just slightly larger than the buns you plan to use, to account for shrinkage during cooking. Set the patties on the baking sheet. Use a spoon to press a dent in the center of each patty so they don\'t puff up as they cook. If you need to stack the patties separate them with a sheet of wax paper.\r\n\r\n4. Preheat the grill or a skillet to medium heat. (Approximately 350-400 degrees F.)\r\n\r\n5. For thick patties: Grill or fry the patties for 3-4 minutes per side.\r\n\r\n6. For thin patties: Cook on the griddle for 2 minutes per side.\r\n\r\n7. Stack the hot patties on hamburgers buns, and top with your favorite hamburgers toppings. Serve warm.', 3, 1, 9, 7, ''),
('Full English Breakfast', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67d100bf41972_breakfast_image.jpg', '1. Preheat oven to 200°F/95°C. Place a large, ovenproof dish in the oven to keep warm.\r\n\r\n2. To a small saucepan, add the beans and keep warm over medium low heat.\r\n\r\n3. Heat a large frying pan over medium heat add the bacon and sausages. Cook until the bacon is cooked and the sausage browned (turning to brown evenly). Transfer to the dish in the oven to keep warm.\r\n\r\n4. To the fat from the bacon (add lard or oil if needed). Cook the mushrooms over medium heat until browned. Tranfer to the oven, keeping the fat in the pan.\r\n\r\n5. Season the tomatoes with salt and add them flesh down to the same pan. Add the black pudding and cook each for 2 minutes per side. Remove and transfer to the dish in the oven.\r\n\r\n6. If needed, add more lard or oil to the pan over medium high heat.Add the bread to the oil (test it by putting in a corner of bread, if it sizzles, it’s ready) and cook until golden brown. Remove to a paper towel to drain.\r\n\r\n7. To the same oil add the eggs and spoon hot oil over the yolks until cooked.\r\n\r\n8. Serve all the components on a plate with the bread on the side.', NULL, 1, 10, 7, 'Breakfast'),
('Nacho Cheese Sauce', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67d1f020c2072_snack_image.jpg', '1. Heat a sauce pan or small pot to medium heat. Add the butter and melt it.\r\n\r\n2. Stir in the flour and stir continuously for 2-3 minutes to form a roux.\r\n\r\n3. Stir in the milk and allow to simmer. It will bubble just a bit around the edges.\r\n\r\n4. Reduce the heat to low, then stir in the cheese a bit at a time. Continue stirring until it all melts through.\r\n\r\n5. Stir in the pickled jalapeno juice (and some of the pickled jalapenos, too, if you want!). Keep stirring until the nacho cheese sauce is nice and smooth.\r\n\r\n6. Taste and adjust for salt, then serve with tortilla chips!', 1, 1, 13, 12, ''),
('Pizza', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67d1f04ccf7d2_369063.jpg', '1. Preheat the oven to 500°F.\r\n\r\n2. In a food processor, place the tomatoes and their juices, olive oil, garlic, and salt. Process until smooth.\r\n\r\n3. Dust a baking sheet with cornmeal. Place the pizza dough on the baking sheet and stretch it into a large oval.\r\n\r\n4. Spread a heaping ½ cup of the tomato sauce* evenly over the pizza dough, leaving a 1-inch border around the edges.\r\n\r\n5. Top with the mozzarella and transfer to the hot oven. Bake for 10 to 12 minutes, or until the crust is browned.\r\n\r\n6. Remove from the oven and top with fresh basil and pinches of red pepper flakes. Drizzle with olive oil and serve.', NULL, 1, 14, 12, ''),
('Macaroni and Cheese', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ec77050169d_mac.jpg', '1. Preheat oven to 325 degrees F and grease a 3 qt baking dish (9x13&quot;).  Set aside.\r\n2. Bring a large pot of salted water to a boil.  When boiling, add dried pasta and cook 1 minute less than the package directs for al dente.  Drain and drizzle with a little bit of olive oil to keep from sticking.\r\n3. While water is coming up to a boil, shred cheeses and toss together to mix, then divide into three piles.  Approximately 3 cups for the sauce, 1 1/2 cups for the inner layer, and 1 1/2 cups for the topping.\r\n4. Melt butter in a large saucepan over MED heat.  Sprinkle in flour and whisk to combine.  Mixture will look like very wet sand.  Cook for approximately 1 minute, whisking often.  Slowly pour in about 2 cups or so of the half and half, while whisking constantly, until smooth.  Slowly pour in the remaining half and half plus the whole milk, while whisking constantly, until combined and smooth.\r\n5.  Continue to heat over MED heat, whisking very often, until thickened to a very thick consistency.  It should almost be the consistency of a semi thinned out condensed soup.\r\n6. Remove from the heat and stir in spices and 1 1/2 cups of the cheeses, stirring to melt and combine.  Stir in another 1 1/2 cups of cheese, and stir until completely melted and smooth. \r\n7. In a large mixing bowl, combine drained pasta with cheese sauce, stirring to combine fully.  Pour half of the pasta mixture into the prepared baking dish.  Top with 1 1/2 cups of shredded cheeses, then top that with the remaining pasta mixture.\r\n8. Sprinkle the top with the last 1 1/2 cups of cheese and bake for 15 minutes, until cheesy is bubbly and lightly golden brown.', 3, 3, 27, 5, 'lunch'),
('Spaghetti Aglio e Olio', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed60e8892bc_67ecd36d9e59a_Simply-Recipes-Spaghetti-Aglio-e-Olio-LEAD-2-c8e7e8c6edb04a8691463c6ea8cd4ba1.jpg', '1. Cook spaghetti according to package directions in salted water until al dente.\r\n2. Reserve 1 cup of pasta water and drain the rest.\r\n3. While the pasta cooks, heat olive oil in a large pan over medium heat.\r\n4. Add sliced garlic to the pan and sauté until golden brown, about 2 minutes.\r\n5. Add red pepper flakes and cook for 30 seconds to release the flavor.\r\n6. Add the cooked spaghetti to the pan with garlic and oil, tossing to coat.\r\n7. Gradually add reserved pasta water, a few tablespoons at a time, to create a light sauce.\r\n8. Season with salt and black pepper to taste.\r\n9. Remove from heat and stir in chopped parsley and grated Parmesan cheese.\r\n10. Serve immediately with extra Parmesan, if desired.', NULL, 3, 54, 36, 'dinner'),
('Chicken Caesar Salad', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed61794f2c3_67ecd4468b3cd_grilled-chicken-caesar-salad_web-6.jpg', '1. Season chicken breasts with olive oil, salt, and black pepper.\r\n2. Cook the chicken on a grill or in a pan over medium heat for 6-7 minutes per side, until fully cooked and internal temperature reaches 165°F.\r\n3. Let the chicken rest for 5 minutes, then slice it into strips.\r\n4. In a large bowl, toss chopped romaine lettuce with Caesar dressing until evenly coated.\r\n5. Add croutons, grated Parmesan cheese, and sliced chicken.\r\n6. Toss again and serve immediately.', NULL, 2, 55, 36, 'lunch'),
('Tandoori Chicken', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed61ee36506_67ecd5b5dee89_1200-by-1200-images-2.jpg', '1. In a bowl, mix yogurt, lemon juice, garlic, ginger, cumin, coriander, turmeric, paprika, garam masala, red chili powder, salt, and olive oil.\r\n2. Make shallow slashes in the chicken thighs and coat them with the marinade.\r\n3. Cover the chicken and refrigerate for at least 2 hours, preferably overnight for deeper flavor.\r\n4. Preheat your oven to 400°F (200°C).\r\n5. Place the chicken on a baking tray and bake for 30-35 minutes, or until the chicken is cooked through and the juices run clear.\r\n6. For an extra smoky flavor, you can finish the chicken under the broiler for 2-3 minutes.\r\n7. For an extra smoky flavor, you can finish the chicken under the broiler for 2-3 minutes.\r\n8. Serve hot with naan or rice.', NULL, 5, 56, 36, 'dinner'),
('Udon Noodles Stir-Fry', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed62424b402_67ecd706af77a_spicy-udon-1200-5-500x375.jpg', '1. Cook the udon noodles according to the package instructions. Drain and set aside.\r\n2. In a large pan or wok, heat 1 tablespoon of olive oil over medium-high heat.\r\n3. Add the minced garlic and grated ginger, and stir-fry for 1-2 minutes until fragrant.\r\n4. Add the julienned carrot, sliced bell pepper, chopped green onions, and sliced mushrooms. Stir-fry for 5-7 minutes until the vegetables start to soften.\r\n5. Push the vegetables to one side of the pan and add another tablespoon of olive oil.\r\n6. Add the cooked udon noodles and stir to combine with the veggies.\r\n7. Pour the soy sauce and sesame oil over the noodles and vegetables, tossing to coat everything evenly.\r\n8. Add the bean sprouts and stir-fry for another 2-3 minutes, letting everything heat through and absorb the flavors.\r\n9. Remove from heat and sprinkle sesame seeds on top.\r\n10. Serve immediately and enjoy!', NULL, 3, 57, 36, 'lunch'),
('Takoyaki', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed62ecefea5_67ecd8d68c022_takoyaki-recipe_done.png', '1. In a bowl, whisk together flour, baking powder, salt, and sugar.\r\n2. Gradually add dashi stock, whisking to form a smooth batter. Add beaten eggs and soy sauce, and mix well.\r\n3. Heat a takoyaki pan over medium heat, lightly greasing each hole with oil.\r\n4. Pour batter into each hole, filling them almost to the top.\r\n5. Add a small piece of octopus, tempura scraps, pickled ginger, and green onions into each hole.\r\n6. Pour more batter over the top, covering the fillings completely.\r\n7. Once the edges begin to set, use a skewer or chopsticks to turn the takoyaki balls, rotating them as they cook. Continue turning until they are golden brown and crispy on the outside (about 3-4 minutes).\r\n8. Transfer the takoyaki to a plate and drizzle with takoyaki sauce, then sprinkle with bonito flakes and seaweed flakes.\r\n9. Serve hot and enjoy!', NULL, 4, 58, 36, 'snack'),
('Ice Cream Sundae', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed63a4bc9a8_67ecd9ed9a253_Ice-cream-sundae-hero-11.jpg', '1. Scoop 2 generous portions of vanilla ice cream into a bowl or sundae dish.\r\n2. Drizzle chocolate syrup and caramel sauce over the ice cream.\r\n3. Top with whipped cream and garnish with a maraschino cherry.\r\n4. Sprinkle crushed nuts, cookie crumbles, and sprinkles on top for extra texture.\r\n5. Optionally, add fresh fruit like strawberry or banana slices.\r\n6. Serve immediately and enjoy your homemade sundae!', NULL, 1, 59, 36, 'dessert'),
('Margherita Pizza', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed640394519_67ecda9170cba_classic-margherita-pizza.jpg', '1. Preheat the oven to 475°F (245°C).\r\n2. Roll out the pizza dough on a floured surface to about 12 inches in diameter.\r\n3. Spread a thin layer of tomato sauce evenly over the dough, leaving a small border around the edges.\r\n4. Tear the fresh mozzarella into pieces and scatter it over the sauce.\r\n5. Bake the pizza in the preheated oven for about 10-12 minutes, or until the crust is golden and the cheese is melted and bubbling.\r\n6. Remove from the oven and immediately scatter fresh basil leaves on top.\r\n7. Drizzle with olive oil and season with salt and black pepper.\r\n8. Sprinkle Parmesan cheese over the top and serve hot.', NULL, 3, 60, 36, 'dinner'),
('Avocado Toast with Poached Egg', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed647115f33_67ecdb217ee4a_Avocado-Egg-Breakfast-Toast-FI-Thumbnail-1200X1200.jpg', '1. Toast the whole wheat bread slices until golden and crispy.\r\n2. While the bread is toasting, fill a small pot with water and bring to a gentle simmer. Add a splash of vinegar.\r\n3. Crack the eggs into separate small bowls, and carefully slide them into the simmering water. Poach the eggs for about 3-4 minutes, until the whites are set but the yolks remain runny.\r\n4. While the eggs are poaching, mash the ripe avocado in a bowl with lemon juice, salt, and black pepper.\r\n5. Spread the mashed avocado generously onto each slice of toasted bread.\r\n6. Once the eggs are ready, gently remove them with a slotted spoon and place one on top of each avocado toast.\r\n7. Drizzle with olive oil, sprinkle with red pepper flakes, and garnish with fresh parsley.\r\n8. Serve immediately and enjoy your nutritious breakfast!', NULL, 2, 61, 36, 'breakfast'),
('Jamaican Jerk Chicken', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed64fea3462_67ecdd53621b7_jamaican-jerk-chicken-FT-RECIPE0918-eabbd55da31f4fa9b74367ef47464351.jpg', '1. In a blender or food processor, combine the scallions, garlic, fresh thyme, scotch bonnet pepper, ground allspice, ground cinnamon, ground nutmeg, brown sugar, soy sauce, lime juice, olive oil, salt, and black pepper. Blend until smooth.\r\n2. Place the chicken thighs in a large bowl or zip-top bag and pour the jerk marinade over them. Coat the chicken well, ensuring it&amp;#039;s evenly covered.\r\n3. Seal the bowl or bag and marinate the chicken in the refrigerator for at least 2 hours, or preferably overnight for more flavor.\r\n4. Preheat your grill or oven to medium-high heat. If grilling, oil the grates lightly to prevent sticking.\r\n5. Grill the chicken for about 30-40 minutes, turning occasionally, until the skin is crispy and the internal temperature reaches 165°F (75°C).\r\n6. If using the oven, bake the chicken at 400°F (200°C) for 35-40 minutes, turning halfway through for even cooking.\r\n7. Once cooked, garnish with fresh cilantro and serve with rice and peas, fried plantains, or a side of your choice.', NULL, 4, 62, 36, 'lunch'),
('Banana Pancakes', 'https://se-dev.cse.buffalo.edu/CSE442/2025-Spring/cse-442ae/uploads/67ed6564e3613_67ecdbf1db38a_20334-banana-pancakes-i-DDMFS-4x3-9f291f03044247d48c9ec26917952402.jpg', '1. In a large bowl, whisk together flour, baking powder, sugar, and salt.\r\n2. In a separate bowl, mash the ripe banana until smooth. Add the milk, egg, melted butter, and vanilla extract, and whisk until combined.\r\n3. Pour the wet ingredients into the dry ingredients and stir until just mixed. Be careful not to over-mix.\r\n4. Heat a non-stick skillet or griddle over medium heat and lightly grease with butter.\r\n5. Pour about 1/4 cup of batter onto the skillet for each pancake. Cook for 2-3 minutes, or until bubbles form on the surface, then flip and cook for another 1-2 minutes until golden brown.\r\n6. Serve warm with maple syrup, fresh fruit, or whipped cream if desired.', NULL, 2, 63, 36, 'breakfast');

